<!--
 * 消息发送表单组件
 *
 * @path apps/message-web/src/views/message/message-form.vue
 * @author ydsz-team
 * @since 1.0.0
 * @modified 4.1.0 由脚手架 CRUD 重写为契约 API：发送表单（MessageSendDTO）提交 send()。
-->
<script lang="ts" setup>
/**
 * 消息（发送表单组件）
 * <p>消费后端契约 MessageController#send（src/api/message.ts，auto-generated by bash/gen-contract.py）：
 * 按 MessageSendDTO 字段（strategy/channel/receiver/bizType/subject/content/templateCode 等）填写发送表单，
 * 提交成功后 emit('success') 并关闭弹窗。
 *
 * @author ydsz-team
 * @since 1.0.0
 */
import { useYDSZModal } from '@ydsz/common-ui';
import { ElForm, ElFormItem } from 'element-plus';
import { reactive, ref } from 'vue';

import { Input, RadioGroup, RadioGroupItem, Select, SelectContent, SelectItem, SelectTrigger, SelectValue, Textarea } from '@ydsz-core/ui-kit/shadcn-ui';
import { send } from '#/api/message';

const emit = defineEmits<{ success: [] }>();

const formRef = ref();

/** 发送表单状态（字段对应 MessageSendDTO） */
interface MessageFormState {
  strategy: 'SYNC' | 'DIRECT' | 'ASYNC' | 'TRANSACTIONAL' | 'BATCH';
  channel: string;
  receiver: string;
  bizType: string;
  subject: string;
  content: string;
  templateCode: string;
  bizId: string;
  priority: string;
  senderId: string;
  messageGroup: string;
}

const formData = reactive<MessageFormState>({
  strategy: 'SYNC',
  channel: '',
  receiver: '',
  bizType: '',
  subject: '',
  content: '',
  templateCode: '',
  bizId: '',
  priority: '',
  senderId: '',
  messageGroup: '',
});

const rules = {
  channel: [{ required: true, message: '请输入发送通道', trigger: 'blur' }],
  receiver: [{ required: true, message: '请输入接收者', trigger: 'blur' }],
};

const [Modal, modalApi] = useYDSZModal({
  onOpenChange: (isOpen: boolean) => {
    if (!isOpen) return;
    Object.assign(formData, {
      strategy: 'SYNC',
      channel: '',
      receiver: '',
      bizType: '',
      subject: '',
      content: '',
      templateCode: '',
      bizId: '',
      priority: '',
      senderId: '',
      messageGroup: '',
    });
  },
  onConfirm: async () => {
    try {
      await formRef.value?.validate();
    } catch {
      return;
    }
    modalApi.lock();
    try {
      await send({
        strategy: formData.strategy,
        channel: formData.channel,
        receiver: formData.receiver,
        bizType: formData.bizType,
        subject: formData.subject,
        content: formData.content,
        templateCode: formData.templateCode || undefined,
        bizId: formData.bizId || undefined,
        priority: formData.priority || undefined,
        senderId: formData.senderId || undefined,
        messageGroup: formData.messageGroup || undefined,
      });
      showToast.success('发送成功');
      emit('success');
      modalApi.close();
    } finally {
      modalApi.unlock();
    }
  },
});
</script>
<template>
  <Modal title="发送消息">
    <ElForm
      ref="formRef"
      :model="formData"
      :rules="rules"
      label-width="100px"
      label-position="right"
    >
      <ElFormItem label="发送策略" prop="strategy">
        <RadioGroup v-model="formData.strategy">
          <RadioGroupItem value="SYNC">同步</RadioGroupItem>
          <RadioGroupItem value="DIRECT">直发</RadioGroupItem>
          <RadioGroupItem value="ASYNC">异步</RadioGroupItem>
          <RadioGroupItem value="TRANSACTIONAL">事务</RadioGroupItem>
        </RadioGroup>
      </ElFormItem>
      <ElFormItem label="通道" prop="channel">
        <Input v-model="formData.channel" placeholder="请输入通道，如 SMS/EMAIL/IN_APP" />
      </ElFormItem>
      <ElFormItem label="接收者" prop="receiver">
        <Input v-model="formData.receiver" placeholder="请输入接收者" />
      </ElFormItem>
      <ElFormItem label="业务类型" prop="bizType">
        <Input v-model="formData.bizType" placeholder="请输入业务类型" />
      </ElFormItem>
      <ElFormItem label="业务ID" prop="bizId">
        <Input v-model="formData.bizId" placeholder="请输入业务ID" />
      </ElFormItem>
      <ElFormItem label="模板编码" prop="templateCode">
        <Input v-model="formData.templateCode" placeholder="请输入模板编码（可为空）" />
      </ElFormItem>
      <ElFormItem label="主题" prop="subject">
        <Input v-model="formData.subject" placeholder="请输入主题（可为空）" />
      </ElFormItem>
      <ElFormItem label="内容" prop="content">
        <Textarea v-model="formData.content" placeholder="请输入内容" />
      </ElFormItem>
      <ElFormItem label="优先级" prop="priority">
        <Select v-model="formData.priority">
          <SelectTrigger>
            <SelectValue placeholder="请选择优先级（可为空）" />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="HIGH">高</SelectItem>
            <SelectItem value="MEDIUM">中</SelectItem>
            <SelectItem value="LOW">低</SelectItem>
          </SelectContent>
        </Select>
      </ElFormItem>
      <ElFormItem label="消息组" prop="messageGroup">
        <Input v-model="formData.messageGroup" placeholder="请输入消息组（可为空）" />
      </ElFormItem>
    </ElForm>
  </Modal>
</template>
